/// Reads a value from raw memory.
///
/// # Safety
///
/// `ptr` must be non-null, properly aligned for `T`, and point to a
/// valid, initialized `T`.
pub unsafe fn read_raw<T>(ptr: *const T) -> T {
    std::ptr::read(ptr)
}

